using Warehouse;

namespace Warehouse.Tests;

[TestClass]
public sealed class InventoryTrackerTests
{
    private InventoryTracker _tracker = null!;

    [TestInitialize]
    public void Setup() => _tracker = new InventoryTracker();

    // ── Stock level basics ──────────────────────────────────────────

    [TestMethod]
    public void GetStockLevel_UnknownSku_ReturnsZero()
    {
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-999"));
    }

    [TestMethod]
    public void AddStock_SingleAdd_IncreasesLevel()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.AreEqual(10, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void AddStock_MultipleAdds_Accumulates()
    {
        _tracker.AddStock("SKU-1", 5);
        _tracker.AddStock("SKU-1", 7);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_ReducesLevel()
    {
        _tracker.AddStock("SKU-1", 20);
        _tracker.RemoveStock("SKU-1", 8);
        Assert.AreEqual(12, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_AllUnits_LeavesZero()
    {
        _tracker.AddStock("SKU-1", 5);
        _tracker.RemoveStock("SKU-1", 5);
        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void RemoveStock_MoreThanAvailable_Throws()
    {
        _tracker.AddStock("SKU-1", 3);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-1", 10));
    }

    [TestMethod]
    public void RemoveStock_FromUnknownSku_Throws()
    {
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.RemoveStock("SKU-NONE", 1));
    }

    // ── Input validation ────────────────────────────────────────────

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddStock_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.AddStock(sku!, 1));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-5)]
    public void AddStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.AddStock("SKU-1", qty));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void RemoveStock_InvalidQuantity_Throws(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.RemoveStock("SKU-1", qty));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void GetStockLevel_InvalidSku_Throws(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(
            () => _tracker.GetStockLevel(sku!));
    }

    // ── Reorder alerts ──────────────────────────────────────────────

    [TestMethod]
    public void NeedsReorder_NoThresholdSet_ReturnsFalse()
    {
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAboveThreshold_ReturnsFalse()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        _tracker.AddStock("SKU-1", 20);
        Assert.IsFalse(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockAtThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 10);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_StockBelowThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 10);
        _tracker.AddStock("SKU-1", 3);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void NeedsReorder_ZeroStockWithThreshold_ReturnsTrue()
    {
        _tracker.SetReorderThreshold("SKU-1", 5);
        Assert.IsTrue(_tracker.NeedsReorder("SKU-1"));
    }

    [TestMethod]
    public void SetReorderThreshold_NegativeThreshold_Throws()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _tracker.SetReorderThreshold("SKU-1", -1));
    }

    // ── Warehouse transfers ─────────────────────────────────────────

    [TestMethod]
    public void TransferStock_MovesUnitsCorrectly()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 50);

        _tracker.TransferStock("SKU-1", 20, destination);

        Assert.AreEqual(30, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(20, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferStock_EntireStock_LeavesSourceAtZero()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 15);

        _tracker.TransferStock("SKU-1", 15, destination);

        Assert.AreEqual(0, _tracker.GetStockLevel("SKU-1"));
        Assert.AreEqual(15, destination.GetStockLevel("SKU-1"));
    }

    [TestMethod]
    public void TransferStock_MoreThanAvailable_Throws()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 5);

        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-1", 10, destination));
    }

    [TestMethod]
    public void TransferStock_NullDestination_Throws()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<ArgumentNullException>(
            () => _tracker.TransferStock("SKU-1", 5, null!));
    }

    [TestMethod]
    public void TransferStock_ToSelf_Throws()
    {
        _tracker.AddStock("SKU-1", 10);
        Assert.ThrowsException<InvalidOperationException>(
            () => _tracker.TransferStock("SKU-1", 5, _tracker));
    }

    [TestMethod]
    public void TransferStock_FailedTransfer_DoesNotAlterSource()
    {
        var destination = new InventoryTracker();
        _tracker.AddStock("SKU-1", 5);

        try { _tracker.TransferStock("SKU-1", 10, destination); }
        catch (InvalidOperationException) { /* expected */ }

        Assert.AreEqual(5, _tracker.GetStockLevel("SKU-1"),
            "Source stock should be unchanged after a failed transfer.");
        Assert.AreEqual(0, destination.GetStockLevel("SKU-1"),
            "Destination should not receive stock from a failed transfer.");
    }

    // ── Multi-SKU isolation ─────────────────────────────────────────

    [TestMethod]
    public void DifferentSkus_AreTrackedIndependently()
    {
        _tracker.AddStock("WIDGET", 10);
        _tracker.AddStock("GADGET", 25);

        _tracker.RemoveStock("WIDGET", 3);

        Assert.AreEqual(7, _tracker.GetStockLevel("WIDGET"));
        Assert.AreEqual(25, _tracker.GetStockLevel("GADGET"));
    }
}

